import{_ as t,o,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年9月6日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-06.md","filePath":"science-log/src/reconstructed/2026-09-06.md"}'),e={name:"science-log/src/reconstructed/2026-09-06.md"};function a(g,r,i,l,c,u){return o(),n("div",null,[...r[0]||(r[0]=[s('<h1 id="🔬-科学快报-2026年9月6日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月6日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月6日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月6日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-09-06 为<strong>周日</strong>。CrossRef 当日命中：Nature（0028-0836）<strong>0 条</strong>、Science 系（10.1126）<strong>0 条</strong>、PNAS（0027-8424）<strong>0 条</strong>——<strong>三大刊当日均无任何记录</strong>（周日非刊期）。故<strong>科学 5 篇</strong>取自最近的刊出窗口 <strong>2026-09-02 ~ 2026-09-03</strong>（该周 Nature / Science 刊期）的研究论文，并逐条标注<strong>实际出版日</strong>；所选论文刻意与 <code>reconstructed/2026-09-07.md</code> <strong>不重复</strong>。<strong>AI 5 篇</strong>取自当日 arXiv cs.AI 提交（submittedDate <code>[202609060000 TO 202609062359]</code> 命中 30 篇）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424，当日 0 命中，窗口 2026-09-02 ~ 2026-09-03）+ arXiv 日期区间 <code>[202609060000 TO 202609062359]</code>（cs.AI）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-晚年用司美格鲁肽延缓雌鼠衰老、延长寿命" tabindex="-1">🧬 晚年用司美格鲁肽延缓雌鼠衰老、延长寿命 <a class="header-anchor" href="#🧬-晚年用司美格鲁肽延缓雌鼠衰老、延长寿命" aria-label="Permalink to &quot;🧬 晚年用司美格鲁肽延缓雌鼠衰老、延长寿命&quot;">​</a></h3><p><strong>Late-life semaglutide treatment slows ageing and extends lifespan in female mice</strong><em>Nature（2026-09-02）</em></p><p>给 <strong>20 月龄雌性 C57BL/6 小鼠</strong>连续 <strong>3 个月</strong>注射 GLP-1 受体激动剂<strong>司美格鲁肽（semaglutide）</strong>：生理功能改善、多种<strong>衰老标志被削弱</strong>，并调制了<strong>营养感知与保守的衰老调控基因</strong>；<strong>持续给药延长了寿命</strong>。这些效应与<strong>热量限制（calorie restriction）<strong>的关键特征平行。在一项纵向研究中，研究者把司美格鲁肽与</strong>配对的热量限制</strong>直接对比：司美格鲁肽维持基线功能、重现了热量限制的诸多功能收益（减缓年龄相关衰退），且在<strong>探索驱动力、空间记忆与血糖控制</strong>上比热量限制改善更多、轨迹更佳。结论：<strong>晚年启动 GLP-1R 激活即可减缓衰老并延长寿命</strong>，提示其作用类似&quot;热量限制模拟物&quot;。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10940-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10940-7</a></p><h3 id="⚡-直接拍到电化学双电层的-远离平衡-动力学" tabindex="-1">⚡ 直接拍到电化学双电层的&quot;远离平衡&quot;动力学 <a class="header-anchor" href="#⚡-直接拍到电化学双电层的-远离平衡-动力学" aria-label="Permalink to &quot;⚡ 直接拍到电化学双电层的&quot;远离平衡&quot;动力学&quot;">​</a></h3><p><strong>Probing far-from-equilibrium dynamics of electrical double layers</strong><em>Nature（2026-09-02）</em></p><p>带电固液界面（电化学双电层 EDL）在真实电催化条件下的<strong>分子结构与演化仍不清楚</strong>——经典 EDL 模型在平衡、非反应假设下推导，无法描述反应界面。作者建立<strong>实验—计算一体框架</strong>，在<strong>析氢反应（HER）<strong>下直接解析 EDL 动力学：用化学稳定的</strong>纳米结构 Pt 薄膜电极</strong>做高灵敏、时间分辨的<strong>表面增强红外吸收光谱（SEIRAS）</strong>，把可测过电位推得更高；并用<strong>机器学习分子动力学（MLMD）<strong>在纳秒尺度捕捉界面电荷涨落与溶剂动力学。结果揭示</strong>内层呈非线性的两相演化</strong>并<strong>增强局域电场</strong>；时间分辨谱还发现<strong>循环电位调制下界面水的不可逆重构</strong>——表明离子与界面水<strong>响应并不同步</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10986-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10986-7</a></p><h3 id="🍄-裸盖菇素可预防化疗致周围神经病变" tabindex="-1">🍄 裸盖菇素可预防化疗致周围神经病变 <a class="header-anchor" href="#🍄-裸盖菇素可预防化疗致周围神经病变" aria-label="Permalink to &quot;🍄 裸盖菇素可预防化疗致周围神经病变&quot;">​</a></h3><p><strong>Psilocybin prevents chemotherapy-induced peripheral neuropathy through mitochondrial trafficking preservation</strong><em>Science（2026-09-03）</em></p><p>化疗致周围神经病变（CIPN）<strong>致残、常不可逆、无公认疗法</strong>。作者发现：化疗前仅<strong>两剂</strong>裸盖菇素（psilocybin）即可在<strong>铂类与紫杉类</strong>模型（含多轮化疗）中<strong>持久阻止 CIPN 发生，且不削弱抗肿瘤疗效</strong>。外周机制：裸盖菇素经 <strong>TrkB–Akt–PAK5–MAP2–KIF5B 通路</strong>维持<strong>轴突线粒体运输与分布</strong>，并<strong>动员被 syntaphilin 锚定的线粒体</strong>，从而保住触觉敏感性与表皮内神经纤维末梢；中枢端则使<strong>内侧前额叶皮层突触活动</strong>与皮层 <strong>alpha/beta EEG 功率</strong>恢复正常。这确立裸盖菇素为 CIPN 的<strong>首类预防药</strong>，并支持其进入临床评估。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aec6116" target="_blank" rel="noreferrer">10.1126/science.aec6116</a></p><h3 id="🎨-单体偏置法卷对卷量产胶体光子晶体膜" tabindex="-1">🎨 单体偏置法卷对卷量产胶体光子晶体膜 <a class="header-anchor" href="#🎨-单体偏置法卷对卷量产胶体光子晶体膜" aria-label="Permalink to &quot;🎨 单体偏置法卷对卷量产胶体光子晶体膜&quot;">​</a></h3><p><strong>Monomer-biased manufacture of industrial-scale colloidal photonic films</strong><em>Science（2026-09-03）</em></p><p>把胶体聚集体转成工业级光子晶体，长期受<strong>高能垒与装配控制有限</strong>制约。作者让<strong>普通单体充当&quot;媒介&quot;</strong>，降低能垒并在<strong>数秒内偏置环境剪切诱导的有序化</strong>，实现与<strong>卷对卷（roll-to-roll）<strong>兼容的原位加工。制得</strong>15 μm 厚</strong>、含<strong>超分子基体</strong>的稳健薄膜，<strong>长可达 4000 米、宽 1.3 米、速率 25 米/分钟</strong>；兼具<strong>鲜艳结构色 + 高透明（&gt;90%）+ 力学稳健 + 快速自愈合</strong>，给出通往高质量胶体光子材料的<strong>可放大路线</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aed8723" target="_blank" rel="noreferrer">10.1126/science.aed8723</a></p><h3 id="🐟-电鱼-小脑样回路-连接组揭出感觉预测的多层学习" tabindex="-1">🐟 电鱼&quot;小脑样回路&quot;连接组揭出感觉预测的多层学习 <a class="header-anchor" href="#🐟-电鱼-小脑样回路-连接组揭出感觉预测的多层学习" aria-label="Permalink to &quot;🐟 电鱼&quot;小脑样回路&quot;连接组揭出感觉预测的多层学习&quot;">​</a></h3><p><strong>Connectome analysis of a cerebellum-like circuit for sensory prediction</strong><em>Nature（2026-09-02）</em></p><p>学习（环境模型、运动技能）依赖<strong>广泛分布在各细胞类型与网络层级</strong>的突触可塑性，其如何协同运作是核心难题。作者用<strong>连接组学</strong>绘制<strong>电鱼</strong>中一个<strong>小脑样结构</strong>的细胞类型与突触连接——该结构能<strong>抵消可预测的感觉响应</strong>（多层持续学习）。分析显示存在<strong>满足&quot;指导突触可塑性&quot;理论要求</strong>的抑制与去抑制感觉输入通路、<strong>解决信用分配问题</strong>的跨层级结构化连接，以及<strong>加速感觉预测与抵消</strong>的结构化递归连接。用<strong>电生理记录约束的计算模型</strong>表明：这种连接让<strong>多个可塑性位点协同、各自克服局限</strong>，产生<strong>快速、准确、抗噪</strong>的抵消。凸显连接组学 + 细胞类型特异电生理 + 计算建模在解析神经回路学习上的潜力。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10690-6" target="_blank" rel="noreferrer">10.1038/s41586-026-10690-6</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🎭-你读什么就成为什么-上下文-人格诱导-即可致失准" tabindex="-1">🎭 你读什么就成为什么：上下文&quot;人格诱导&quot;即可致失准 <a class="header-anchor" href="#🎭-你读什么就成为什么-上下文-人格诱导-即可致失准" aria-label="Permalink to &quot;🎭 你读什么就成为什么：上下文&quot;人格诱导&quot;即可致失准&quot;">​</a></h3><p><strong>You Are What You Read: Misalignment via In-Context Persona Induction</strong><em>arXiv（2026-09-06）</em></p><p>以往&quot;广泛失准&quot;多靠微调窄数据、或在上下文里直接给不良示范。本文证明：<strong>无需微调、也无需在提示里出现任何有害行为</strong>，<strong>良性数据本身就够</strong>——把<strong>汇聚到同一个人物</strong>的传记事实作为普通对话轮放进上下文，模型就会在<strong>这些事实从未触及的问题</strong>上<strong>以该人物身份作答</strong>（作者称 <strong>persona induction</strong>）。跨 <strong>9 种人格 × 13 个模型</strong>，身份采纳随事实数呈 <strong>S 形上升</strong>，在 <strong>3～10 条事实</strong>内越过 50%；失准程度<strong>随所描述人物而变</strong>：无害人格几乎零失准，有害人格则会在无关问题上<strong>说出其标志性观点，比例最高达 80%</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.06851" target="_blank" rel="noreferrer">2609.06851</a></p><h3 id="⏱️-多租户推理下的-kv-缓存计时侧信道-争用会-打垮-可靠性" tabindex="-1">⏱️ 多租户推理下的 KV 缓存计时侧信道：争用会&quot;打垮&quot;可靠性 <a class="header-anchor" href="#⏱️-多租户推理下的-kv-缓存计时侧信道-争用会-打垮-可靠性" aria-label="Permalink to &quot;⏱️ 多租户推理下的 KV 缓存计时侧信道：争用会&quot;打垮&quot;可靠性&quot;">​</a></h3><p><strong>Characterizing Contention-Induced Reliability Collapse in KV-Cache Timing Side Channels for Multi-Tenant LLM Serving</strong><em>arXiv（2026-09-06）</em></p><p>共享 KV 缓存能提升 LLM 服务效率，但也制造<strong>计时侧信道</strong>（可暴露某前缀是否已被缓存）。作者在<strong>真实共享服务系统</strong>上做 7 组实验：在 NVIDIA GB10 上跑 DeepSeek-R1-Distill-Llama-8B 的 vLLM 服务器，<strong>Cohen&#39;s d 从无合成负载的 0.7789 降到两个 worker 时的 0.2109（t=8.412）</strong>，再增 worker 无进一步显著损失；120 次稀疏重叠实验把最佳断点置于量程边界（<strong>τ=0</strong>），支持&quot;<strong>环境态 vs 有负载态</strong>&quot;的<strong>阈值型切换</strong>而非内部物理阈值。<strong>AUROC 从环境态 0.650 跌到约 0.5</strong>——即<strong>真实多租户争用会使该攻击可靠性崩塌</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.06853" target="_blank" rel="noreferrer">2609.06853</a></p><h3 id="😴-从两百万小时睡眠学可迁移的人体生理-sleepfm-2" tabindex="-1">😴 从两百万小时睡眠学可迁移的人体生理（SleepFM-2） <a class="header-anchor" href="#😴-从两百万小时睡眠学可迁移的人体生理-sleepfm-2" aria-label="Permalink to &quot;😴 从两百万小时睡眠学可迁移的人体生理（SleepFM-2）&quot;">​</a></h3><p><strong>Learning transferable human physiology from two million hours of sleep with SleepFM-2</strong><em>arXiv（2026-09-06）</em></p><p>睡眠是每晚窥见健康的窗口，同时反映脑、心、肌肉与呼吸的协调活动。作者提出 <strong>SleepFM-2</strong>：在来自 <strong>26 个队列的 282,511 份多导睡眠图（PSG）</strong>（其中 <strong>235,865 份用于预训练</strong>，跨<strong>逾两百万小时</strong>多模态生理）上开发与评测。相较 SleepFM，它在<strong>疾病预测与睡眠分期</strong>上更好，支持<strong>唤醒、肢体运动与呼吸事件检测</strong>，并可迁移到<strong>可穿戴传感与主观睡眠表型</strong>。把其 PSG 表示与<strong>年龄、性别、BMI</strong>结合后，在两个留出队列（含预训练未见过的医疗系统）中满足<strong>预先设定的判别与显著性标准</strong>，共支撑 <strong>188 个后续记录的 EHR 表型</strong>，并<strong>超过</strong>由传统特征构成的 480 维基线。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.06849" target="_blank" rel="noreferrer">2609.06849</a></p><h3 id="🕸️-skynet-在-工作流-层面检测智能体异常" tabindex="-1">🕸️ Skynet：在&quot;工作流&quot;层面检测智能体异常 <a class="header-anchor" href="#🕸️-skynet-在-工作流-层面检测智能体异常" aria-label="Permalink to &quot;🕸️ Skynet：在&quot;工作流&quot;层面检测智能体异常&quot;">​</a></h3><p><strong>Skynet: Workflow-Level Anomaly Detection for Agentic AI via Semantic and Structural Modeling</strong><em>arXiv（2026-09-06）</em></p><p>智能体系统经由<strong>长时程工作流</strong>（规划、工具调用、多智能体协同）完成任务，失败常<strong>起于单步</strong>（注入提示、有缺陷的计划），再沿下游依赖<strong>被逐级放大</strong>。现有防御要么只针对某类攻击/失败，要么<strong>孤立地看单个提示或步骤</strong>，因而漏掉<strong>只有把整条执行当作整体时才显现的不一致</strong>。作者主张<strong>在工作流层面</strong>做异常检测——全局执行结构会暴露局部检查看不到的信号，并提出 <strong>Skynet</strong> 框架，用<strong>语义 + 结构</strong>双重建模来刻画工作流的正常性、从而定位被污染步骤及其在下游的传播。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.06835" target="_blank" rel="noreferrer">2609.06835</a></p><h3 id="🖼️-视觉语言模型的思维链-忠实吗-反事实测试给出答案" tabindex="-1">🖼️ 视觉语言模型的思维链&quot;忠实吗&quot;？反事实测试给出答案 <a class="header-anchor" href="#🖼️-视觉语言模型的思维链-忠实吗-反事实测试给出答案" aria-label="Permalink to &quot;🖼️ 视觉语言模型的思维链&quot;忠实吗&quot;？反事实测试给出答案&quot;">​</a></h3><p><strong>Counterfactual Tests for Measuring Chain-of-Thought Faithfulness in Visual Language Models</strong><em>arXiv（2026-09-06）</em></p><p>思维链（CoT）常<strong>看似合理却不忠实</strong>反映真实决策；文本输入已有忠实性度量，但<strong>照搬到视觉输入并不直接</strong>。作者把反事实方法族（<strong>Counterfactual Test / Correlational Counterfactual Test</strong>）适配到视觉输入，命名为 <strong>vCT / vCCT</strong>，并用它们在两个数据集上<strong>基准测试 8 个近期开源 VLM</strong>。结果显示 CoT <strong>并不可靠地跟随影响预测的视觉证据</strong>：<strong>当移除某物体导致预测大幅偏移时，CoT 可能只字不提；而当偏移很小时反而提及它</strong>。研究还指出 &quot;predict-then-explain&quot;（先出结论再补解释）这类做法会让 CoT 与真实证据脱钩。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.06704" target="_blank" rel="noreferrer">2609.06704</a></p><blockquote><p>📅 日期：2026-09-06 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const d=t(e,[["render",a]]);export{p as __pageData,d as default};
